args.newString:
export function parseTransactions(lines) {
  const transactions = [];

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    if (line.trim() === '') continue;

    const fields = line.split('|').map(field => field.trim());
    if (fields.length !== 4 || fields.some(field => field === '')) {
      throw new TypeError(`Invalid ledger line at index ${index}`);
    }
    const [id, account, kind, amount] = fields;
    transactions.push({ id, account, kind, amount });
  }

  return transactions;
}

